mapper.select:
select ID, STOCK_DATE, BEAD_CODE, STOCK_NUM, MODIFY_NUM, BAD_NUM, REMARK, IS_DELETE, CREATE_BY, CREATE_TIME, UPDATE_BY, UPDATE_TIME
from t_tq_stock
where IS_DELETE = '0'

    and ID != #{entity.id}


    and STOCK_DATE = #{entity.stockDate}


    and BEAD_CODE = #{entity.beadCode}

