SET IS_DELETE = 1,
    UPDATE_BY = #{updateBy},
    UPDATE_TIME = #{updateTime}
WHERE DATE_FORMAT(STOCK_DATE, '%Y-%m-%d') = #{stockDateStr}
  AND IS_DELETE = 0
